package hugolib_test

import (
	"testing"

	"github.com/gohugoio/hugo/hugolib"
)

func TestScratchRebuildTwoPages(t *testing.T) {
	t.Parallel()

	files := `
-- hugo.toml --
disableKinds = ['rss','sitemap','taxonomy','term']
-- layouts/_default/list.html --
{{ .Content }}
-- layouts/_default/single.html --
{{ .Content }}
-- content/_index.md --
---
title: home
---
home-content|
-- content/p1/index.md --
---
title: p1
---
p1-content|
`

	b := hugolib.Test(t, files, hugolib.TestOptRunning())

	b.AssertFileContent("public/index.html", "home-content|")
	b.AssertFileContent("public/p1/index.html", "p1-content|")

	b.EditFiles("content/_index.md", "home-content|foo", "content/p1/index.md", "p1-content|bar")

	b.AssertFileContent("public/index.html", "home-content|foo")
	b.AssertFileContent("public/p1/index.html", "p1-content|bar")
}

func TestScratchRebuildSinglePage(t *testing.T) {
	t.Parallel()

	files := `
-- hugo.toml --
disableKinds = ['rss','sitemap','taxonomy','term']
