func (s *contentNodeShifter) Insert(old, new contentNodeI) contentNodeI {
	switch vv := old.(type) {
	case *pageState:
		newp, ok := new.(*pageState)
		if !ok {
			panic(fmt.Sprintf("unknown type %T", new))
		}
		oldCommon := vv.pageCommon
		newCommon := newp.pageCommon
		oldSite := oldCommon.s
		newSite := newCommon.s
		oldLang := oldSite.languagei
		newLang := newSite.languagei
		if oldLang == newLang {
			return new
		}
		mergedPages := make(contentNodeIs, s.numLanguages)
		mergedPages[newLang] = new
		mergedPages[oldLang] = old
		return mergedPages
	case contentNodeIs:
		newp, ok := new.(*pageState)
		if !ok {
			panic(fmt.Sprintf("unknown type %T", new))
		}
		newCommon := newp.pageCommon
		newSite := newCommon.s
		newLang := newSite.languagei
		existing := vv[newLang]
		if !types.IsNil(existing) {
			existing.MarkStale()
		}
		vv[newLang] = new
		return vv
	case *resourceSource:
		newp, ok := new.(*resourceSource)
		if !ok {
			panic(fmt.Sprintf("unknown type %T", new))
		}
		var oldLang int
		oldResource := vv.r
		if oldResource != nil {
			if _, isPage := oldResource.(page.Page); isPage {
				oldPage := oldResource.(*pageState)
				oldSite := oldPage.s
				oldLang = oldSite.languagei
			} else {
				oldFile := vv.fi
				oldMeta := oldFile.Meta()
				oldLang = oldMeta.LangIndex
			}
		} else {
			oldFile := vv.fi
			oldMeta := oldFile.Meta()
			oldLang = oldMeta.LangIndex
		}
		var newLang int
		newResource := newp.r
		if newResource != nil {
			if _, isPage := newResource.(page.Page); isPage {
				newPage := newResource.(*pageState)
				newSite := newPage.s
				newLang = newSite.languagei
			} else {
				newFile := newp.fi
				newMeta := newFile.Meta()
				newLang = newMeta.LangIndex
			}
		} else {
			newFile := newp.fi
			newMeta := newFile.Meta()
			newLang = newMeta.LangIndex
		}
		if oldLang == newLang {
			return new
		}
		mergedResources := make(resourceSources, s.numLanguages)
		mergedResources[newLang] = newp
		mergedResources[oldLang] = vv
		return mergedResources
	case resourceSources:
		newp, ok := new.(*resourceSource)
		if !ok {
			panic(fmt.Sprintf("unknown type %T", new))
		}
		newLang := newp.LangIndex()
		existing := vv[newLang]
		if !types.IsNil(existing) {
			existing.MarkStale()
		}
		vv[newLang] = newp
		return vv
	default:
		panic(fmt.Sprintf("unknown type %T", old))
	}
